#!/usr/bin/env node

/**
 * Transcribe Skill for OpenClaw
 * Converts audio (e.g., WhatsApp voice messages) to text using Whisper.
 * Works offline and aims for <2s transcription for short notes.
 *
 * Usage: node transcribe.js --audioFile <path> [--language <code>]
 * Example: node transcribe.js --audioFile "voice.ogg" --language en
 *
 * Outputs JSON to stdout: { "text": "transcribed text" }
 */

const fs = require('fs');
const path = require('path');
const { pipeline } = require('@xenova/transformers');
const ffmpeg = require('fluent-ffmpeg');
const ffmpegPath = require('@ffmpeg-installer/ffmpeg').path;

// Set ffmpeg path
ffmpeg.setFfmpegPath(ffmpegPath);

// Configuration - can be overridden via environment variable
const MODEL = process.env.WHISPER_MODEL || 'openai/whisper-tiny'; // Use tiny for fastest speed (~2s)
const DEVICE = process.env.WHISPER_DEVICE || 'cpu'; // 'cpu' or 'cuda' (if GPU available)
const TASK = 'automatic-speech-recognition';

// Cache the pipeline to avoid reloading model on every call
let transcribePipeline = null;

/**
 * Initialize the transcription pipeline
 */
async function getPipeline() {
  if (transcribePipeline) return transcribePipeline;

  console.error(`[Transcribe] Loading Whisper model: ${MODEL} on ${DEVICE}...`);
  transcribePipeline = await pipeline(TASK, MODEL, {
    device: DEVICE,
    quantized: true, // Use quantized model for smaller size and faster inference
  });
  console.error('[Transcribe] Model loaded.');
  return transcribePipeline;
}

/**
 * Convert audio file to WAV format (16kHz, mono, PCM) required by Whisper
 * Returns path to the temporary WAV file
 */
function convertToWav(inputPath, outputPath) {
  return new Promise((resolve, reject) => {
    ffmpeg(inputPath)
      .toFormat('wav')
      .audioFrequency(16000)
      .audioChannels(1)
      .audioCodec('pcm_s16le')
      .on('end', () => {
        resolve(outputPath);
      })
      .on('error', (err) => {
        fs.unlink(outputPath, () => {}); // Cleanup
        reject(err);
      })
      .save(outputPath);
  });
}

/**
 * Transcribe audio file to text
 *
 * @param {string} audioFile - Path to the input audio (OGG, Opus, MP3, WAV, etc.)
 * @param {string} [language] - Optional language code (e.g., 'en', 'hi'). If not provided, auto-detection is used.
 * @returns {Promise<string>} Transcribed text
 */
async function transcribeAudio(audioFile, language) {
  if (!fs.existsSync(audioFile)) {
    throw new Error(`Audio file not found: ${audioFile}`);
  }

  // Get absolute paths
  const absAudioPath = path.resolve(audioFile);
  const tempWavPath = path.join(
    path.dirname(absAudioPath),
    `transcribe_temp_${Date.now()}.wav`
  );

  try {
    // Step 1: Convert to WAV if needed
    console.error(`[Transcribe] Converting audio to WAV...`);
    await convertToWav(absAudioPath, tempWavPath);

    // Step 2: Load pipeline (and cache)
    const pipe = await getPipeline();

    // Step 3: Run transcription
    console.error(`[Transcribe] Transcribing...`);
    const startTime = Date.now();

    const params = {
      audio: tempWavPath,
    };
    if (language) {
      params.parameters = {
        language: language,
        task: 'transcribe',
      };
    }

    const output = await pipe(params);
    const text = typeof output === 'string' ? output : (output.text || output[0]?.text || '');

    const duration = ((Date.now() - startTime) / 1000).toFixed(2);
    console.error(`[Transcribe] Completed in ${duration}s`);

    return text.trim();
  } finally {
    // Cleanup temp WAV file
    if (fs.existsSync(tempWavPath)) {
      fs.unlink(tempWavPath, (err) => {
        if (err) console.error('[Transcribe] Failed to delete temp file:', err);
      });
    }
  }
}

/**
 * Parse command line arguments
 */
function parseArgs() {
  const args = process.argv.slice(2);
  const options = { audioFile: null, language: null };

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--audioFile' && i + 1 < args.length) {
      options.audioFile = args[++i];
    } else if (args[i] === '--language' && i + 1 < args.length) {
      options.language = args[++i];
    }
  }

  return options;
}

// If run directly from command line
if (require.main === module) {
  const { audioFile, language } = parseArgs();

  if (!audioFile) {
    console.error('Error: --audioFile is required');
    process.exit(1);
  }

  transcribeAudio(audioFile, language)
    .then(text => {
      // Output result as JSON to stdout
      console.log(JSON.stringify({ text }));
    })
    .catch(err => {
      console.error('Error:', err.message);
      process.exit(1);
    });
}

// Export for programmatic use
module.exports = { transcribeAudio, getPipeline };

