arguments.command:
powershell -Command "
# Stop service
nssm stop OpenClawGateway 2>$null; sc stop OpenClawGateway 2>$null; Start-Sleep -Seconds 2;

# Kill all related console processes
Get-Process | Where-Object { $_.ProcessName -in @('cmd','powershell','node') -and ($_.CommandLine -match 'openclaw' -or $_.CommandLine -match 'gateway') } | Stop-Process -Force;

# Disable and delete any scheduled task containing openclaw/gateway (case insensitive)
$tasks = Get-ScheduledTask | Where-Object { $_.TaskName -like '*openclaw*' -or $_.TaskName -like '*gateway*' };
foreach ($t in $tasks) {
  Disable-ScheduledTask -TaskName $t.TaskName -Confirm:$false -ErrorAction SilentlyContinue;
  Unregister-ScheduledTask -TaskName $t.TaskName -Confirm:$false -ErrorAction SilentlyContinue;
}

# Remove startup shortcuts
$startup = [Environment]::GetFolderPath('Startup');
Get-ChildItem $startup | Where-Object { $_.Name -like '*openclaw*' -or $_.Name -like '*gateway*' } | Remove-Item -Force -ErrorAction SilentlyContinue;

# Remove Run registry entries (current user and local machine)
$runKeys = @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Run','HKLM:\Software\Microsoft\Windows\CurrentVersion\Run');
foreach ($key in $runKeys) {
  if (Test-Path $key) {
    Get-ItemProperty $key | ForEach-Object {
      $_.PSObject.Properties | Where-Object { $_.Value -like '*openclaw*' -or $_.Value -like '*gateway*' } | ForEach-Object {
        Remove-ItemProperty -Path $key -Name $_.Name -ErrorAction SilentlyContinue;
      }
    }
  }
}

# Start service again
nssm start OpenClawGateway;
Start-Sleep -Seconds 3;
Write-Host 'Cleanup complete. Service restarted.'
"
